// First node MUST verify the shared secret (jobs-mcp spec §6, v1-mandatory).
// The value lives in the LXC env (/etc/n8n/n8n.env), never in this JSON.
const req = $input.first().json;
const secret = $env.JOBS_WEBHOOK_SECRET;
const presented = (req.headers || {})['x-jobs-webhook-secret'];
if (!secret || presented !== secret) {
  return [{ json: { ok: false, error: { code: 'unauthorized', message: 'missing or invalid webhook secret' } } }];
}
const body = req.body || {};
// Defense in depth: jobs-mcp already validated payload against the registry
// schema; re-check so an authenticated-but-forged call still cannot smuggle
// an arbitrary string into the reingest argument.
const corpus = (body.payload || {}).corpus;
if (typeof corpus !== 'string' || !/^[a-z0-9][a-z0-9-]{1,62}$/.test(corpus)) {
  return [{ json: { ok: false, error: { code: 'E_SCHEMA', message: 'payload.corpus is required and must be a corpus name' } } }];
}
// The executor's ONLY action is one MCP tools/call of `reingest` (knowledge
// spec §6): it fetches nothing and holds no content. The scoped n8n-reingest
// token is attached by the HTTP node from $env.KNOWLEDGE_REINGEST_TOKEN.
return [{ json: {
  ok: true, job_id: body.job_id ?? null, attempt: body.attempt ?? null, corpus,
  rpc: { jsonrpc: '2.0', id: String(body.job_id ?? 'manual'), method: 'tools/call', params: { name: 'reingest', arguments: { corpus } } },
} }];

// Turn the MCP reply into the jobs-mcp completion report (jobs spec §6).
// Streamable HTTP answers tools/call as SSE ("event: message\ndata: {...}");
// a plain JSON body is handled the same way.
const res = $input.first().json; // fullResponse: {data|body, headers, statusCode}
// n8n's HTTP node (v4, fullResponse + text) files the body under `data`
// (its outputPropertyName default); `body` is checked as a fallback.
const raw = res.data ?? res.body;
const text = typeof raw === 'string' ? raw : JSON.stringify(raw ?? '');
let payload = null;
for (const line of text.split(/\r?\n/)) if (line.startsWith('data:')) payload = line.slice(5).trim();
if (payload === null) payload = text.trim();
let rpc = null;
try { rpc = JSON.parse(payload); } catch {}
// jobs-mcp keeps error.message (cap 1024) but the terminal error.code is always
// retries_exhausted — so the message must carry the diagnosis on its own.
const fail = (code, message) => [{ json: { ok: false, error: { code, message: String(message).slice(0, 1000) } } }];
if (res.statusCode !== 200 || !rpc) return fail('knowledge_http_error', `knowledge-mcp returned ${res.statusCode}${rpc && rpc.code ? ' ' + rpc.code : ''}`);
if (rpc.error) return fail('knowledge_rpc_error', rpc.error.message ?? 'rpc error');
let tool = null;
try { tool = JSON.parse(rpc.result?.content?.[0]?.text ?? ''); } catch {}
if (!tool) return fail('knowledge_bad_response', 'unparseable tool result');
if (rpc.result?.isError) return fail(String(tool.code ?? 'E_INTERNAL').slice(0, 64), tool.message ?? 'tool error');
// Clean-sweep rule (knowledge spec §6): per-doc errors mean index_as_of did
// NOT advance — report the attempt failed so jobs-mcp retries (reingest is
// sha-keyed, so the retry only redoes what failed) and the job state shows it.
if (Array.isArray(tool.errors) && tool.errors.length > 0) {
  // Name the documents (repo-relative path after owner/repo/ref): the pod log
  // holds only the count and ok:false results are never persisted by jobs-mcp.
  const named = tool.errors.slice(0, 5).map((e) => `${e.code} ${String(e.uri ?? '').split('/').slice(6).join('/')}`).join('; ');
  return fail('reingest_partial', `${tool.errors.length} document(s) failed: ${named}`);
}
return [{ json: {
  ok: true,
  result: { corpus: tool.corpus, source_ref: tool.source_ref, indexed: tool.indexed, unchanged: tool.unchanged, tombstoned: tool.tombstoned },
  artifacts: [],
  spent_usd: 0,
} }];
